<?php $repo=new ControlCenter();$cid=(int)($camp['id']??0);$counts=[];foreach(['games'=>'กิจกรรม','sub_teams'=>'ทีม','users'=>'สตาฟ'] as $table=>$label){$q=db()->prepare('SELECT COUNT(*) FROM '.$table.($table==='users'?' WHERE is_active=1':' WHERE camp_id=?'));$q->execute($table==='users'?[]:[$cid]);$counts[$label]=$q->fetchColumn();}$q=db()->prepare("SELECT COUNT(*) FROM competition_matches m JOIN competition_rounds r ON r.id=m.round_id WHERE r.camp_id=? AND m.status='playing'");$q->execute([$cid]);$counts['แมตช์กำลังแข่ง']=$q->fetchColumn(); ?>
<h1>สวัสดี <?= e($user['name']) ?></h1><div class="rra-stats"><?php foreach($counts as $label=>$count): ?><section class="panel"><span><?= e($label) ?></span><strong><?= e($count) ?></strong></section><?php endforeach ?></div>
<?php foreach(['การจัดการทีม'=>['camp-settings'=>['ข้อมูลงาน','ชื่อและรายละเอียดค่าย'],'teams'=>['จัดการทีมหลักและทีมย่อย','ทีมหลัก A, B, C และทีมย่อย A1, A2'],'staff'=>['บัญชีผู้ใช้','จัดการสตาฟและสิทธิ์']],'การแข่งขัน'=>['games'=>['จัดการกิจกรรม','กติกา เกณฑ์คะแนน และจำนวนรอบ'],'scoreboard'=>['ตารางคะแนน','คะแนนรวมและประวัติปรับคะแนน'],'arenas'=>['สนามแข่งขัน','สนามที่ใช้ร่วมกันในกิจกรรม'],'competition'=>['จัดการแข่งขัน','จับคู่และจัดตารางการแข่งขัน'],'scoring'=>['บันทึกคะแนน','ให้คะแนนและยืนยันผลแมตช์'],'displays'=>['จอแสดงผล','ควบคุมจอทีวีและโปรเจกเตอร์']],'งานค่าย'=>['timeline'=>['กำหนดการ','กิจกรรมและงานของทีมงาน'],'media'=>['สื่อการเรียนรู้','บทเรียน รูป และวิดีโอ'],'equipment'=>['เช็กลิสต์อุปกรณ์','เตรียมอุปกรณ์ก่อนเริ่มค่าย']]] as $section=>$cards): ?><h2><?= e($section) ?></h2><div class="rra-grid"><?php foreach($cards as $target=>[$label,$description]): if($user['role']!=='main_staff'&&in_array($target,['staff','camp-settings']))continue; ?><a class="panel rra-card" href="<?= e(url($target)) ?>"><span class="rra-card-icon">◇</span><h3><?= e($label) ?></h3><p><?= e($description) ?></p></a><?php endforeach ?></div><?php endforeach ?>
